#include <cstddef>
#include <stdexcept>
#include <vector>

void RotateSquareClockwise(std::vector<std::vector<int>>& a) {
    const std::size_t n = a.size();
    if (n > 128) throw std::invalid_argument("dimension must be <= 128");
    for (const auto& row : a) {
        if (row.size() != n)
            throw std::invalid_argument("matrix must be square");
    }

    for (std::size_t layer = 0; layer < n / 2; ++layer) {
        const std::size_t last = n - 1 - layer;
        for (std::size_t col = layer; col < last; ++col) {
            const std::size_t offset = col - layer;
            const int top = a[layer][col];

            a[layer][col] = a[last - offset][layer];
            a[last - offset][layer] = a[last][last - offset];
            a[last][last - offset] = a[col][last];
            a[col][last] = top;
        }
    }
}
